<script setup lang="ts">
const props=defineProps<{game:any;command:any}>()
const finance=computed(()=>props.command?.finance)
const forecast=computed(()=>props.command?.advanceForecasts?.find((f:any)=>f.turns===28))
const nextBill=computed(()=>(props.command?.agenda??[]).find((item:any)=>item.tab==='finance'))
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n/100)
</script>
<template><div v-if="finance" class="company-finance">
 <section class="panel finance-runway"><span class="eyebrow">SUSTENTABILIDADE DA COMPANHIA</span><h2>{{finance.weeklyTotalCents===0?'Sem despesas semanais atuais':finance.runwayWeeks===0?'Caixa abaixo de uma semana':finance.runwayWeeks+' semanas de autonomia'}}</h2><p>Estimativa com o caixa atual, descontadas as dívidas, para manter salários e sede. Novas receitas, compras e contratações futuras podem alterar esse prazo.</p><p v-if="finance.totalArrearsCents" class="purchase-issue">Há {{money(finance.totalArrearsCents)}} em atraso. A quitação ocorre automaticamente ao avançar quando houver caixa suficiente.</p><p v-else-if="finance.runwayWeeks!==null&&finance.runwayWeeks<=1" class="purchase-issue">Revise os compromissos antes de assumir novas despesas.</p></section>
 <div class="stats finance-stats"><section class="stat"><span>DESPESA SEMANAL</span><strong>{{money(finance.weeklyTotalCents)}}</strong><small>Salários {{money(finance.weeklySalariesCents)}} · sede {{money(finance.weeklyInfrastructureCents)}}</small></section></div>
 <section class="panel finance-outlook"><h3>Plano atual e próximos compromissos</h3><dl class="review-money"><div><dt>Ordens para confirmar</dt><dd>{{command.pendingOrders?.length||0}}</dd></div><div v-if="command.pendingOrders?.length"><dt>Despesas das ordens</dt><dd>{{money(command.plannedExpensesCents)}}</dd></div><div v-if="command.plannedIncomeCents"><dt>Receitas líquidas previstas nas ordens</dt><dd>{{money(command.plannedIncomeCents)}}</dd></div><div v-if="command.pendingOrders?.length"><dt>Saldo após ordens</dt><dd>{{money(command.projectedCashCents)}}</dd></div><template v-if="forecast"><div><dt>Compromissos nos próximos 28 turnos</dt><dd>{{money(forecast.obligationsCents)}}</dd></div><div class="review-total"><dt>Saldo previsto no turno {{forecast.throughTurn}}</dt><dd>{{money(forecast.cashAfterObligationsCents)}}</dd></div></template></dl><p v-if="command.planningError" class="purchase-issue">{{command.planningError}}</p><p v-else-if="!forecast" class="form-hint">Previsão indisponível. Confira as ordens e os compromissos antes de avançar.</p><p v-else class="form-hint">Inclui o plano atual e despesas conhecidas. Resultados e receitas futuras de missões não entram na estimativa.</p><p v-if="nextBill" class="next-bill">Próximo compromisso: <strong>{{nextBill.title}}</strong> · turno {{nextBill.dueTurn}} · em {{Math.max(0,nextBill.dueTurn-game.currentTurn)}} turnos.</p></section>
</div><p v-else role="status">Carregando resumo financeiro…</p></template>
